import json
import os

KIT = r"D:\EbbingRainbow\sci_fi_interior_20fbx\WFC_Kit"
OUT = r"D:\EbbingRainbow\Source\EbbingRainbow\WFC\Arch\WFCKitTileTable.h"

data = json.load(open(os.path.join(KIT, "tilesets", "kit.json"), encoding="utf-8"))
walls = [t for t in data["tiles"] if t["layer"] == "wall"]
floors = [t for t in data["tiles"] if t["layer"] == "floor"]
ceils = [t for t in data["tiles"] if t["layer"] == "ceiling"]
props = [t for t in data["tiles"] if t["layer"] == "prop"]
DIRS = ("north", "east", "south", "west")

lines = [
    "// GENERATED by Scripts/gen_tile_table.py - do not edit by hand.",
    "#pragma once",
    '#include "CoreMinimal.h"',
    "",
    "struct FWFCKitWallEntry",
    "{",
    "\tconst TCHAR* Id;",
    "\tconst TCHAR* Pattern;",
    "\tfloat Weight;",
    "\tbool bEmpty;",
    "};",
    "",
    "static const FWFCKitWallEntry GWFCKitWallEntries[] =",
    "{",
]
for t in walls:
    pat = "".join(t["sockets"][d] for d in DIRS)
    lines.append('\t{ TEXT("%s"), TEXT("%s"), %.3ff, %s },' % (
        t["id"], pat, float(t.get("weight", 1.0)),
        "true" if t.get("empty") else "false"))
lines += ["};", "", "static const TCHAR* GWFCKitFloorIds[] =", "{"]
for t in floors:
    lines.append('\tTEXT("%s"),' % t["id"])
lines += ["};", "", "static const TCHAR* GWFCKitCeilIds[] =", "{"]
for t in ceils:
    lines.append('\tTEXT("%s"),' % t["id"])
lines += ["};", "", "static const TCHAR* GWFCKitPropIds[] =", "{"]
for t in props:
    lines.append('\tTEXT("%s"),' % t["id"])
lines += ["};", ""]

os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w", encoding="utf-8") as f:
    f.write("\n".join(lines))
print(OUT, len(walls), len(floors), len(ceils), len(props))
